def find_all_hollow_rectangles(grid):
    """Find all hollow rectangles and mark which are innermost."""
    h, w = len(grid), len(grid[0])
    all_rects = []  # List of (r, c, size)
    innermost = set()  # Set of (r, c)-tuples for innermost rectangles

    for r in range(h):
        for c in range(w):
            for size in range(1, 12):
                br, bc = r + size, c + size
                if br >= h or bc >= w:
                    break

                corner_val = grid[r][c]
                if grid[r][bc] != corner_val or grid[br][c] != corner_val or grid[br][bc] != corner_val:
                    continue

                is_hollow = True
                for i in range(r, br + 1):
                    for j in range(c, bc + 1):
                        if i == r or i == br or j == c or j == bc:
                            if grid[i][j] != corner_val:
                                is_hollow = False
                                break
                    if not is_hollow:
                        break

                if is_hollow:
                    all_rects.append((r, c, size))

    # A rectangle is innermost if no other rectangle covers its interior
    for name, r, c, size in [(name, r, c, size) for name, r, c, size in enumerate(all_rects)]:
        br, bc = r + size, c + size
        rect_cells = set((r + i, c + j) for i in range(size) for j in range(size))
        border = set((i, j) for i in range(r, br + 1) for j in range(c, bc + 1) 
                      if i == r or i == br or j == c or j == bc)
        interior = rect_cells - border

        is_innermost = True
        for nr, nc, ns in all_rects:
            # Skip self
            if name == (nr, nc, ns):
                continue
            nbr, nbc = nr + ns, nc + ns
            ninterior = {(ni, nj) for ni in range(nr + 1, nbr) for nj in range(nc + 1, nbc)}
            # If this rectangle's interior contains a cell from another rectangle's interior
            if interior & ninterior:
                is_innermost = False
                break

        if is_innermost:
            innermost.add((r, c))

    return all_rects, innermost

