import json

def find_hollow_rectangles_and_interiors(grid):
    """Find all hollow rectangles and determine which cells are interiors."""
    h, w = len(grid), len(grid[0])

    # Find all rectangles that have the same-colored corner and form a closed loop
    hollow_rects = []  # List of (top_row, left_col, size, corner_color)

    for r in range(h):
        for c in range(w):
            for size in range(3, 15):  # Need at least size 3 to have interior
                br, bc = r + size, c + size
                if br >= h or bc >= w:
                    break

                corner_val = grid[r][c]
                if corner_val == 5:  # Skip background
                    continue

                # Check all 4 corners
                if grid[r][bc] != corner_val or grid[br][c] != corner_val or grid[br][bc] != corner_val:
                    continue

                # Check all border cells
                is_closed = True
                for i in range(r, br + 1):
                    for j in range(c, bc + 1):
                        if i == r or i == br or j == c or j == bc:
                            if grid[i][j] != corner_val:
                                is_closed = False
                                break
                    if not is_closed:
                        break

                if is_closed:
                    hollow_rects.append((r, c, size, corner_val))

    return hollow_rects

def get_both_innermost_rectangles_all(grid):
    """Get all innermost rectangles (not containing any other hollow rectangle)"""
    h, w = len(grid), len(grid[0])

    # Find all hollow rectangles
    all_hollow = []
    for r in range(h):
        for c in range(w):
            for size in range(3, 15):
                br, bc = r + size, c + size
                if br >= h or bc >= w:
                    break

                corner_val = grid[r][c]
                if corner_val == 5:
                    continue

                is_closed = True
                for i in range(r, br + 1):
                    for j in range(c, bc + 1):
                        if i == r or i == br or j == c or j == bc:
                            if grid[i][j] != corner_val:
                                is_closed = False
                                break
                    if not is_closed:
                        break

                if is_closed:
                    # Interior cells
                    interior = set((r+1+i, c+1+j) for i in range(size-2) for j in range(size-2))
                    all_hollow.append(interior)

    # Find rectangles that don't contain any other rectangle's interior
    innermost = []
    for i, rect1 in enumerate(all_hollow):
        is_innermost = True
        for j, rect2 in enumerate(all_hollow):
            if i == j:
                continue
            # Check if rect2's interior is contained in rect1's interior
            if rect1.issuperset(rect2):
                is_innermost = False
                break
        if is_innermost:
            innermost.append(rect1)

    return innermost

def transform(grid):
    """Transform grid by filling hollow rectangle interiors."""
    result = [row[:] for row in grid]

    innermost_rects = get_both_innermost_rectangles_all(grid)

    # For each cell in innermost rectangles, determine fill value
    filled_cells = []
    for rect in innermost_rects:
        # Size is based on rect dimensions
        max_r = max(r for r, c in rect)
        max_c = max(c for r, c in rect)
        min_r = min(r for r, c in rect)
        min_c = min(c for r, c in rect)

        size = (max_r - min_r) + 1
        interior_size = size - 2

        # Rule: even interior size → 2, odd interior size → 7
        size_code = interior_size  # This is inner size like 1, 2, 3...
