def find_innermost_frames(frames):
    """Find frames whose interiors don't overlap with other frames' interiors."""
    innermost = []
    seen = set()

    for i, (r1, c1, s1, v1) in enumerate(frames):
        int_cells = {(r1+1+ir, c1+1+ic) for ir in range(s1-2) for ic in range(s1-2)}

        is_innermost = True
        for (r2, c2, s2, v2) in frames:
            # Skip same frame
            if (r2, c2, s2, v2) == (r1, c1, s1, v1):
                continue

            int_cells2 = {(r2+1+ir, c2+1+ic) for ir in range(s2-2) for ic in range(s2-2)}

            # If interiors overlap, this frame is not innermost
            overlap = int_cells & int_cells2
            if overlap:
                is_innermost = False
                break

        if is_innermost and int_cells:
            innermost.append((r1, c1, s1, v1, int_cells))

